auth.probe_js:
// Mastodon renders its own state into the document: <script id="initial-state" type="application/json">
// carries meta.me (the logged-in account id) and meta.access_token (the token the web UI itself
// uses for every API call). The session cookie (_session_id) is HttpOnly, so document.cookie is
// not usable here — and is not needed.
// VERIFIED SIGNED-OUT on mastodon.social 4.8.0-alpha (2026-09-12): the #initial-state element is
// PRESENT, meta.access_token is null and meta.me is absent. The element existing is not the
// verdict; the fields are.
let st = null;
try {
  const el = document.getElementById('initial-state');
  if (!el) return {signed_in:false, why:'no #initial-state element — this is not a mastodon web-UI document'};
  st = JSON.parse(el.textContent || 'null');
} catch (e) { return {signed_in:false, why:'#initial-state unparseable: ' + e.message}; }
const meta = (st && st.meta) || {};
if (!meta.me || !meta.access_token) return {signed_in:false, why:'#initial-state present but meta.me/meta.access_token empty'};
const domain = meta.domain || location.host;
let as = null;
try {
  const local = ((st && st.accounts) || {})[meta.me] || {};
  as = local.acct || local.username || null;
} catch (e) { as = null; }
if (!as) {
  // meta.me alone is only a numeric id; ask the instance for the handle. 401/403 here means the
  // embedded token is dead, which IS a signed-out session.
  try {
    const r = await fetch('/api/v1/accounts/verify_credentials', {
      credentials: 'include',
      headers: {authorization: 'Bearer ' + meta.access_token, accept: 'application/json'}
    });
    if (r.status === 401 || r.status === 403) return {signed_in:false, why:'verify_credentials ' + r.status + ' — the token in #initial-state is dead'};
    const j = await r.json();
    if (j && j.username) as = j.acct || j.username;
  } catch (e) { /* network/CORS only — do not flip the verdict on it */ }
}
// Never return meta.access_token. Handle + instance only.
return {signed_in:true, as: (as ? as : 'id:' + meta.me) + '@' + domain};
